# ## Step 7 — A Simple Agent Loop Using the Dispatcher
#
# Now let's build a simple agent loop that:
# 1. Calls the LLM with a system prompt and user message
# 2. If the LLM returns a tool call (imagined as a field in the response), dispatch it through our dispatcher
# 3. Feed the result back to the LLM
#
# For this demo, we'll ask the LLM to classify a user intent (rather than actually parse tool calls), but we'll dispatch the classification request itself.

# %%
# Demo: LLM-based intent classification with dispatcher

async def classify_intent_handler(query: str):
    """Handler that calls the LLM to classify intent."""
    system = "You are an intent classifier. Respond with exactly one word: greeting, question, or command."
    msg = f"Classify this user message: '{query}'"
    resp = await lrn_llm.call(
        [{"role": "user", "content": msg}],
        system=system,
        max_tokens=10
    )
    intent = lrn_llm.text(resp).strip().lower()
    return {"intent": intent, "query": query}

dispatcher = MiniDispatcher(max_attempts=2, timeout_s=10.0)

# Dispatch a single call
result = await dispatcher.dispatch(
    classify_intent_handler("Hello, how are you?"),
    timeout_s=10.0
)

if isinstance(result, DispatchOk):
    print(f"✅ Intent classification succeeded (attempts: {result.attempts})")
    print(f"   Result: {result.result}")
else:
    print(f"❌ Dispatch failed: {result.kind} after {result.attempts} attempt(s)")
    print(f"   {result.message}")

# %% [markdown]
# ## Step 8 — Multi-Tool Dispatch with Concurrency Limit
#
# When the agent needs to call multiple tools (or make multiple LLM requests), we use a semaphore to limit concurrency. Let's dispatch several classification tasks in parallel, bounded to 2 concurrent calls.

# %%
# Multi-dispatch with concurrency limit

class ConcurrentDispatcher(MiniDispatcher):
    def __init__(self, max_attempts=3, timeout_s=5.0, concurrency=2):
        super().__init__(max_attempts, timeout_s)
        self._sem = asyncio.Semaphore(concurrency)
    
    async def dispatch(self, handler_coro, timeout_s=None):
        async with self._sem:
            return await super().dispatch(handler_coro, timeout_s)
    
    async def dispatch_many(self, coros):
        """Dispatch multiple coroutines with bounded concurrency."""
        return await asyncio.gather(*[self.dispatch(c) for c in coros])

conc_dispatcher = ConcurrentDispatcher(max_attempts=2, timeout_s=10.0, concurrency=2)

# Create multiple classification tasks
tasks = [
    classify_intent_handler("What time is it?"),
    classify_intent_handler("Please send an email."),
    classify_intent_handler("Hi there!"),
]

results = await conc_dispatcher.dispatch_many(tasks)

print(f"Dispatched {len(results)} tasks with concurrency limit=2")
for i, res in enumerate(results):
    if isinstance(res, DispatchOk):
        print(f"  Task {i}: {res.result['intent']} (attempts={res.attempts})")
    else:
        print(f"  Task {i}: {res.kind}")

